TP.register({id:"lp1-g2",lp:1,grade:"2",mode:"baseline",nextGrade:"3rd grade",build(E){const F=E.F;const ico=(n,px)=>(E.F.icon||E.F.pic2)(n,px)||n;const INK="#6B4A3C",PUPIL="#4A332A",BLUSH="#F49AAB";const SILVER="#D3DADF",COPPER="#D08A5C";const kEye=(x,y,r)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="${PUPIL}"/>`;const kBlush=(x,y,r)=>`<ellipse cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" rx="${(r*1.5).toFixed(1)}" ry="${(r*.95).toFixed(1)}" fill="${BLUSH}" opacity=".88"/>`;const kSmile=(x,y,w,sw)=>`<path d="M${(x-w).toFixed(1)} ${y.toFixed(1)} q${w.toFixed(1)} ${(w*1.05).toFixed(1)} ${(w*2).toFixed(1)} 0" fill="none" stroke="${PUPIL}" stroke-width="${sw.toFixed(1)}" stroke-linecap="round"/>`;const kFace=(cx,cy,r)=>kEye(cx-r*.38,cy-r*.06,r*.16)+kEye(cx+r*.38,cy-r*.06,r*.16)+kBlush(cx-r*.72,cy+r*.3,r*.17)+kBlush(cx+r*.72,cy+r*.3,r*.17)+kSmile(cx,cy+r*.3,r*.21,Math.max(1.3,r*.1));const kCounter=(x,y,r,fill)=>{const base=`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="${Math.max(1.8,r*.16).toFixed(1)}"/>`;return r<9?base:base+kFace(x,y,r)};const kStar=(cx,cy,R,fill,withFace)=>{let d="";for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?R*.45:R;d+=(i?"L":"M")+(cx+Math.cos(a)*rr).toFixed(1)+" "+(cy+Math.sin(a)*rr).toFixed(1)+" "}return`<path d="${d}Z" fill="${fill}" stroke="${INK}" stroke-width="${(R*.13).toFixed(1)}" stroke-linejoin="round" stroke-linecap="round"/>`+(withFace?kFace(cx,cy+R*.06,R*.44):"")};const FABLE="Crow played all summer. Mouse was busy dragging dry leaves into her hole. “Why are you working so hard?” asked Crow. “The rainy season is coming,” said Mouse. Crow laughed. “I have plenty of time!” One gray morning, the rain began. Water dripped into Crow’s nest. She was cold and soaked. “May I come in?” she asked sadly. Mouse let her stay, and the next day they fixed the nest together. Crow was thankful. She never waited until the last minute again.";const OTTER="Sea otters live in the ocean near California. They do not have blubber like whales. Thick fur keeps them warm. Otters float on their backs and use rocks to crack open clam shells. When they sleep, they wrap up in kelp so they do not drift away. A group of resting otters is called a raft.";const TURTLES="Sea turtles live in warm oceans around the world. They come up to the top of the water. There they breathe air. A mother sea turtle crawls onto a beach. The beach is sandy. She comes at night. She digs a hole with her back flippers. She lays about one hundred eggs. Then she covers the nest with sand. She goes back to the sea. About two months later, the baby turtles hatch. They hurry to the water.";const WORDS=["hope","tap","boat","cloud","chew","rainbow","unlock","helpful","laugh","busy","snoat","plaim"];function starArray(rows,cols){let s=`<svg viewBox="0 0 ${cols*70+20} ${rows*70+20}" width="${cols*70+20}" role="img" aria-label="${rows} rows of ${cols} stars">`;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){s+=kStar(c*70+45,r*70+41,26,"#FBD873",true)}return s+"</svg>"}function dots(n,seed){const pts=[];let x=seed;const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};while(pts.length<n){const p=[30+rnd()*220,30+rnd()*180];if(pts.every(q=>Math.hypot(q[0]-p[0],q[1]-p[1])>34))pts.push(p)}return`<svg viewBox="0 0 280 240" width="280" role="img" aria-label="Group of dots"><rect x="4" y="4" width="272" height="232" rx="22" fill="none" stroke="var(--line)" stroke-width="3"/>`+pts.map(p=>kCounter(+p[0].toFixed(0),+p[1].toFixed(0),13,"#8ECBE8")).join("")+"</svg>"}function clock(h,m){const cx=130,cy=124,R=108;let s=`<svg viewBox="0 0 260 260" width="260" role="img" aria-label="Analog clock">`;s+=`<path d="M${cx-62} ${cy+R-14} l-12 34 M${cx+62} ${cy+R-14} l12 34" stroke="${INK}" stroke-width="11" stroke-linecap="round"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+9}" fill="#F3DCC4" stroke="${INK}" stroke-width="5"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="#FDF6E6" stroke="${INK}" stroke-width="4"/>`;for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*76}" y="${cy-Math.cos(a)*76}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="${PUPIL}" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:12;s+=`<line x1="${cx+Math.sin(a)*(R-4)}" y1="${cy-Math.cos(a)*(R-4)}" x2="${cx+Math.sin(a)*(R-4-l)}" y2="${cy-Math.cos(a)*(R-4-l)}" stroke="${INK}" stroke-width="${i%5?1.5:3}" stroke-linecap="round"/>`}s+=F.dialFace(cx,cy+34,33);const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*52}" y2="${cy-Math.cos(ha)*52}" stroke="${PUPIL}" stroke-width="9" stroke-linecap="round"/>`;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*84}" y2="${cy-Math.cos(ma)*84}" stroke="#4E8FA3" stroke-width="5" stroke-linecap="round"/>`;s+=`<circle cx="${cx}" cy="${cy}" r="7" fill="${PUPIL}"/>`;return s+`</svg>`}function coinFace(C,r){return`<circle cx="${(C-r*.3).toFixed(1)}" cy="${(C-r*.46).toFixed(1)}" r="${(r*.11).toFixed(1)}" fill="${PUPIL}"/><circle cx="${(C+r*.3).toFixed(1)}" cy="${(C-r*.46).toFixed(1)}" r="${(r*.11).toFixed(1)}" fill="${PUPIL}"/>`+kBlush(C-r*.62,C-r*.2,r*.133)+kBlush(C+r*.62,C-r*.2,r*.133)}function coin(name,r,fill){const C=r+4;return`<svg viewBox="0 0 ${r*2+8} ${r*2+8}" width="${r*2+8}" role="img" aria-label="${name}"><circle cx="${C}" cy="${C}" r="${r}" fill="${fill}" stroke="${INK}" stroke-width="3"/><circle cx="${C}" cy="${C}" r="${r-4}" fill="none" stroke="${INK}" stroke-width="1.4" opacity=".45"/>${coinFace(C,r)}<text x="${C}" y="${C+r*.22}" font-size="${Math.max(12,r/2.6)}" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="${PUPIL}">${name}</text></svg>`}function graphHtml(){const data=[["Apples",5],["Bananas",3],["Grapes",7],["Oranges",E.state.oranges||0]],cell=40,x0=70,y0=30,rows=8;let s=`<svg viewBox="0 0 500 440" width="500" role="img" aria-label="Bar graph of favorite fruits">`;s+=`<text x="270" y="20" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" font-size="22" fill="var(--ink)">Our Favorite Fruits</text>`;for(let r=0;r<=rows;r++){const y=y0+10+(rows-r)*cell;s+=`<line x1="${x0}" y1="${y}" x2="${x0+data.length*100}" y2="${y}" stroke="var(--line)" stroke-width="2"/><text x="${x0-12}" y="${y}" text-anchor="end" dominant-baseline="central" font-size="18" fill="var(--ink)">${r}</text>`}data.forEach((d,i)=>{const bx=x0+i*100+20;for(let r=0;r<rows;r++){const y=y0+10+(rows-r-1)*cell,filled=r<d[1];if(i===3)s+=`<rect class="oc" data-r="${r+1}" x="${bx}" y="${y}" width="60" height="${cell}" rx="6" fill="${filled?"#FBD873":"transparent"}" stroke="${filled?INK:"#5E8FA8"}" stroke-dasharray="${filled?"0":"4 4"}" stroke-width="2" style="cursor:pointer"/>`;else if(filled)s+=`<rect x="${bx}" y="${y}" width="60" height="${cell}" rx="6" fill="#8ECBE8" stroke="${INK}" stroke-width="2"/>`}s+=`<text x="${bx+30}" y="${y0+10+rows*cell+26}" text-anchor="middle" font-size="18" font-weight="700" fill="var(--ink)">${d[0]}</text>`});return s+"</svg>"}const lookBack=(label,text)=>`<details class="look-back" open><summary>Look back at ${label}</summary><p class="passage" style="font-size:1.5rem">${text}</p></details>`;const WRITE_DIR="Write on your paper. When you finish, hold it up. Or read it to your teacher.";const STOPS=[{id:1,title:"Word Flip",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:120,dir:"Read each word out loud. The last two are silly words. Just sound them out.",desc:"reading words with long and short vowels, vowel teams, a prefix, a suffix, and irregular spellings",key:["Read each word. snoat and plaim are silly words: listen for the oa and ai vowel team sounds.","Watch for: long vs short vowel (hope, tap), vowel teams (boat, cloud, chew, rainbow), prefix and suffix (unlock, helpful), irregular words (laugh, busy)."]}]},{id:2,title:"Read the Fable",parts:[{std:["RF.2.4"],kind:"read",n:82,label:"words read correctly",dur:120,dir:"Read the story out loud. Use your best reading voice.",desc:"an 82-word grade-level fable read aloud",html:()=>`<p class="passage">${FABLE}</p>`,key:["82 words. Mark each missed word and each self-correction on the passage in the record sheet.","Note pace and expression in your notes."]}]},{id:3,title:"Story Questions",short:"Story",parts:[{title:"Story Questions",std:["RL.2.1"],dur:60,dir:"Answer each question out loud.",desc:"why and what questions about key details in a fable",qs:["Why was Mouse working so hard?","What happened to Crow when the rain came?"],key:["The rainy season was coming, so she was getting her home ready (dragging dry leaves into her hole). (RL.2.1)","Her nest got wet, she was cold and soaked, and she asked to stay with Mouse. (RL.2.1)"]},{title:"Retell and Lesson",std:["RL.2.2"],dur:60,dir:"Tell the story in your own words. Then answer out loud.",desc:"retelling a fable and telling its lesson",qs:["Tell me what happened in the story, from beginning to end.","What lesson did Crow learn?"],key:["Retells in order: Crow played while Mouse worked, the rain came and soaked Crow’s nest, Mouse let her in, they fixed the nest together. (RL.2.2)","Get ready ahead of time. Don’t wait until the last minute. (RL.2.2)"]}]},{id:4,title:"Listen and Read",short:"Listen",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:90,read:OTTER,dir:"Listen first. Then answer your teacher’s questions out loud.",desc:"describing key details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ico("otter",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read about sea otters.</p>`,key:["What keeps otters warm? (thick fur)","Why do they wrap up in kelp? (so they don’t drift away)","“Tell me two more things you learned about sea otters.” (any two: they live in the ocean near California, they have no blubber, they float on their backs, they use rocks to crack open clam shells, a group of resting otters is called a raft)","Describe how an otter opens a clam shell. (it floats on its back and uses a rock to crack the shell open)"]},{title:"Listen and Answer",std:["RI.2.1"],dur:120,dir:"Read about sea turtles. Then answer each question out loud.",desc:"where, when, how, and what questions about an informational text the student read",html:()=>`<h3 style="margin:18px 0 4px;color:var(--sea)">Sea Turtles</h3><p class="passage" style="font-size:1.4rem;line-height:1.65;max-width:none">${TURTLES}</p>`,qs:["Where do sea turtles live?","When does the mother turtle crawl onto the beach?","How does she make her nest?","What do baby turtles do after they hatch?"],key:["In warm oceans around the world (RI.2.1)","At night (RI.2.1)","She digs a hole with her back flippers, lays her eggs, and covers the nest with sand (RI.2.1)","They hurry to the water (RI.2.1)"]},{title:"Find It and Write It",std:["W.2.8"],dur:120,read:TURTLES,dir:"Listen while your teacher reads the Sea Turtles text again. Then find your answers. Say the first two out loud. Write the last one on your paper and hold it up.",desc:"gathering information from a text on the page to answer questions",qs:["About how many eggs does a mother sea turtle lay? Find the part of the text that tells you.","About how long is it before the eggs hatch?","Write one sentence to answer this question: Why does a sea turtle come up to the top of the water? Use a fact from the text."],key:["About one hundred. The student should point to the sentence about digging a hole and laying the eggs (W.2.8)","About two months (W.2.8)","Writes a sentence built on the fact in the text, for example: A sea turtle comes up to the top of the water to breathe air (W.2.8)"]}]},{id:5,title:"Fix It Fast",parts:[{title:"Say It Right",std:["L.2.1"],dur:60,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular plural, irregular past tense, reflexive pronoun, making a sentence longer)",qs:["One mouse, two ____.","Today I tell. Yesterday I ____.","I did it all by ____.","Make it longer: “The otter swam.”"],key:["mice (L.2.1)","told (L.2.1)","myself (L.2.1)","Adds a detail and stays a complete sentence (The little otter swam fast in the cold ocean.) (L.2.1)"]},{title:"Write It Right",std:["L.2.2"],dur:85,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters, an apostrophe in a contraction, a comma in a letter greeting, spelling a vowel team word)",qs:["Fix this sentence: <b>the otters sleep near california</b>","Write <b>is not</b> as one short word.","This is the start of a letter. Write it and add the missing mark: <b>Dear Mouse</b>","Listen. Write the word your teacher says."],key:["The otters sleep near California. (capital T, capital C, and a period) (L.2.2)","isn’t (with the apostrophe) (L.2.2)","Dear Mouse, (comma after Mouse) (L.2.2)","Say: “Float. Otters float on their backs.” The student writes float (oa vowel team). (L.2.2)"]}]},{id:6,title:"Tell Me a Story",short:"Tell a Story",parts:[{std:["SL.2.4"],n:4,label:"checks met",dur:60,dir:"Tell your story out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you helped someone.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>`,key:["Tells events in order","Uses descriptive details","Speaks in complete sentences","Loud enough to hear"]}]},{id:7,title:"Number Card",parts:[{title:"What Is It Worth?",std:["2.NBT.A.1"],dur:45,dir:"Look at the number. Answer out loud.",desc:"telling the value of a digit in a three-digit number",fig:()=>`<p class="huge">748</p>`,qs:["What is the 4 worth?","What is the 7 worth?","What is the 8 worth?"],key:["40, or 4 tens (2.NBT.A.1)","700, or 7 hundreds (2.NBT.A.1)","8, or 8 ones (2.NBT.A.1)"]},{title:"Write the Number",std:["2.NBT.A.3"],dur:35,dir:"Write your answers on your paper and hold it up.",desc:"writing a number in expanded form and writing a number from its name",qs:["Write 748 in expanded form.","Write “three hundred sixty” as a number."],key:["700 + 40 + 8 (2.NBT.A.3)","360 (2.NBT.A.3)"]},{title:"Count It",std:["2.NBT.A.2"],dur:35,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 100s",qs:["Count out loud from 596 to 612.","Skip count by 100s from 230 to 930."],key:["596, 597 ... 599, 600, 601 ... 612. Watch the jump past 599 (2.NBT.A.2)","230, 330, 430 ... 930 (2.NBT.A.2)"]}]},{id:8,title:"Stars and Dots",parts:[{title:"Star Array",std:["2.OA.C.4"],dur:30,dir:"Look at the stars. Write your adding sentence on your paper and hold it up.",desc:"finding the total of an array and writing it as a sum of equal addends",fig:()=>`<div class="figure">${starArray(4,3)}</div>`,qs:["How many stars in all?","Write an adding sentence for them."],key:["12 stars (2.OA.C.4)","3 + 3 + 3 + 3 = 12 or 4 + 4 + 4 = 12 (2.OA.C.4)"]},{title:"Odd or Even",std:["2.OA.C.3"],dur:45,dir:"Look at the dots. Answer out loud. Write the double on your paper.",desc:"telling odd from even and writing an even number as a double",fig:()=>`<div class="figure"><div>${dots(12,7)}<p class="fig-label">Group A</p></div><div>${dots(15,31)}<p class="fig-label">Group B</p></div></div>`,qs:["Is Group A odd or even? Write it as a double.","Is Group B odd or even?"],key:["Group A has 12: even, 6 + 6 (2.OA.C.3)","Group B has 15: odd (2.OA.C.3)"]}]},{id:9,title:"Word Problems",short:"Problems",parts:[{title:"One Step",std:["2.OA.A.1"],dur:140,dir:"Read the problem. Write your number sentence on your paper and hold it up.",desc:"one-step take-from, compare and put-together word problems within 100 with the unknown in different places",qs:["Mia had 52 stickers. She gave some away. Now she has 27. How many did she give away? Write a number sentence with a box for the number you don’t know.","Ben picked 34 apples. Rosa picked 18 more apples than Ben. How many did Rosa pick? Write a number sentence.","There are 45 books on the shelf. 28 are picture books and the rest are chapter books. How many are chapter books? Write a number sentence.","Rosa counted 84 shells. Ben counted 57 shells. How many more shells did Rosa count than Ben? Write a number sentence."],key:["52 - □ = 27 or 27 + □ = 52; answer 25 (2.OA.A.1)","34 + 18 = 52; answer 52 apples (2.OA.A.1)","45 - 28 = 17 or 28 + □ = 45; answer 17 chapter books (2.OA.A.1)","84 - 57 = 27 or 57 + □ = 84; answer 27 more shells (2.OA.A.1)"]},{title:"Two Steps",std:["2.OA.A.1"],dur:100,dir:"These problems have two steps. Read each one. Solve it on your paper and say your answer.",desc:"two-step addition and subtraction word problems within 100",qs:["Mia had 45 shells. She found 28 more. Then she gave 16 shells to a friend. How many shells does Mia have now?","There were 90 beads in the jar. Ben used 35 beads for one bracelet and 24 beads for another. How many beads are left?"],key:["57 shells (45 + 28 = 73, then 73 - 16 = 57) (2.OA.A.1)","31 beads (90 - 35 = 55, then 55 - 24 = 31; or 35 + 24 = 59, then 90 - 59 = 31) (2.OA.A.1)"]},{title:"Big Numbers",std:["2.NBT.B.7"],dur:110,dir:"Solve on your paper. Show your work and hold it up.",desc:"adding and subtracting three-digit numbers with regrouping and showing a strategy",qs:["Solve 356 + 248. Show how you did it.","Solve 500 - 237. Show how you did it.","Solve 487 + 165. Show how you did it."],key:["604, shows place value strategy or drawing (2.NBT.B.7)","263, regroups across the two zeros, or counts up from 237 (2.NBT.B.7)","652, regroups in both the ones and the tens (2.NBT.B.7)"]}]},{id:10,title:"Money and Time",parts:[{title:"Money",std:["2.MD.C.8"],dur:85,dir:"Count the coins. Write the amount on your paper and hold it up.",desc:"counting coins, writing a dollar amount, and finding change, using the dollar sign and the cent sign",fig:()=>`<div class="figure"><div class="row center">${coin("quarter",46,SILVER)}${coin("quarter",46,SILVER)}${coin("dime",32,SILVER)}${coin("penny",36,COPPER)}${coin("penny",36,COPPER)}${coin("penny",36,COPPER)}</div></div>`,qs:["Maya has these coins in her pocket. How much money does she have? Write it with the right symbol.","Leo has 2 one-dollar bills and 3 quarters. Write how much money he has.","A pencil costs 45¢. You pay with 2 quarters. How much change do you get?"],key:["63¢ (2.MD.C.8). $0.63 is also correct, but 63¢ is the grade 2 target.","$2.75 (2.MD.C.8). The dollar sign is part of the answer.","5¢ (2.MD.C.8). Two quarters is 50¢, and 50 - 45 = 5."]},{title:"Time",std:["2.MD.C.7"],dur:45,dir:"Look at the clock. Write the time on your paper. Then answer out loud.",desc:"telling time to five minutes with a.m. or p.m. and knowing the minutes in an hour",fig:()=>`<div class="figure">${clock(8,50)}</div>`,qs:["You eat breakfast at this time. Write the time. Is it a.m. or p.m.?","How many minutes are in an hour?"],key:["8:50 a.m. (2.MD.C.7)","60 minutes (2.MD.C.7)"]}]},{id:11,title:"Fruit Graph",parts:[{std:["2.MD.D.10"],n:3,dur:90,dir:"Tell your teacher how high to make the Oranges bar. Then answer the questions out loud.",desc:"finishing a bar graph with four categories and solving compare and put-together problems from it",html:()=>`<p class="big" style="margin-top:0">2 kids like oranges. Finish the graph.</p>`,render:()=>`<div class="figure">${graphHtml()}</div>`,bind:(root,ctx)=>root.querySelectorAll(".oc").forEach(r=>r.onclick=()=>{const v=+r.dataset.r;E.state.oranges=(E.state.oranges||0)===v?v-1:v;E.save();ctx.redraw()}),qs:["How many more kids like grapes than bananas?","How many kids like apples and oranges together?"],key:["Oranges bar filled to 2. Click the squares as the student tells you, or have them draw it on paper.","Grapes (7) minus bananas (3) = 4 more","Apples (5) plus oranges (2) = 7"]}]},{id:12,title:"Measure and Shapes",short:"Measure",parts:[{title:"Measure It",std:["2.MD.A.1"],dur:45,dir:"Get a ruler and a spoon. Measure the spoon. Then answer out loud.",mats:["a ruler","a spoon"],desc:"measuring an object with a ruler and choosing the right measuring tool",qs:["Measure your spoon with a ruler. How long is it?","What tool would you use to measure a couch?"],key:["Lines up the ruler at 0 and gives a reasonable length with units (2.MD.A.1)","Yardstick or measuring tape (2.MD.A.1)"]},{title:"Shapes",std:["2.G.A.1"],dur:30,dir:"Draw on your paper and hold it up. Then answer out loud.",desc:"drawing and naming a five-sided shape and counting the faces of a cube",qs:["Draw a shape with 5 sides. What is it called?","How many faces does a cube have?"],key:["Pentagon (2.G.A.1)","6 (2.G.A.1)"]}]},{id:13,title:"Write About It",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Letter to Crow",icon:"✉️",hint:"Tell Crow what you think"},std:["W.2.1"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"an opinion letter about the fable",html:()=>`<p class="big">Write a letter to Crow. Should she have gotten ready sooner? Tell her why, using the story. Write 3 or 4 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Start with: Dear Crow</li><li>End with: Your friend and your name</li></ul>${lookBack("the story",FABLE)}`,key:["States an opinion (W.2.1)","Gives a reason from the story (W.2.1)","Uses a linking word like because or also (W.2.1)","Ends with a closing sentence (W.2.1)"]},{alt:{group:"write",key:"facts",label:"Turtle Facts",icon:"🐢",hint:"Teach about sea turtles"},std:["W.2.2"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"an informative piece about sea turtles",html:()=>`<p class="big">Write about sea turtles. Teach your reader 2 or more facts from Sea Turtles. Write 3 or 4 sentences.</p>${lookBack("Sea Turtles",TURTLES)}`,key:["Introduces the topic (W.2.2)","Gives 2 or more facts about sea turtles (W.2.2)","The facts stay on the topic and are true to the Sea Turtles text (W.2.2)","Ends with a closing sentence (W.2.2)"]},{alt:{group:"write",key:"story",label:"My Story",icon:"🎒",hint:"Tell about a time you got ready"},std:["W.2.3"],n:4,label:"checks met",dur:210,dir:WRITE_DIR,desc:"a narrative about a real experience",html:()=>`<p class="big">Think of a time you got ready for something, like a trip, a game, or a rainy day. What did you do to get ready? Write a story about it. Write 3 or 4 sentences.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">First</span><span class="pill" style="font-size:1.4rem">Next</span><span class="pill" style="font-size:1.4rem">Last</span></div>`,key:["Tells about one event or a short set of events in order (W.2.3)","Includes details about actions, thoughts, or feelings (W.2.3)","Uses time words like first, next, then, or last (W.2.3)","Gives a sense of closure (W.2.3)"]}]},{id:14,title:"Sun, Water and the Seed Patch",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">The crew put three young palm shoots in sand on the deck and watched them for two weeks.</p>
     <table class="bigTable"><tr><th>Shoot</th><th>What it got</th><th>How it looked after two weeks</th></tr>
     <tr><td>1</td><td>sunlight and water</td><td>tall and green, 4 new leaves</td></tr>
     <tr><td>2</td><td>sunlight, no water</td><td>droopy and dry, no new leaves</td></tr>
     <tr><td>3</td><td>water, no sunlight</td><td>pale and thin, 1 small leaf</td></tr></table>
     <div class="figure">${ico("palm",88)}${ico("sprout",88)}</div>`,qs:["Which shoot grew best, and what did it get?","Shoot 2 had plenty of sunlight. Why did it do so badly?","You want to test only whether a shoot needs sunlight. Name one thing you would keep the same for both shoots, and name the one thing you would change."],key:["Shoot 1. It got both sunlight and water.","It got no water. Sunlight on its own was not enough, so water is something a plant needs too.","Keep the same: the same amount of water, the same sand, the same size shoot, the same spot out of the wind. Change only one thing: one shoot in the sunlight and one in the dark. A student who changes two things has not made a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves pollen or seeds",html:()=>`<p class="big">On the island, bees carry pollen from flower to flower, and parrots carry seeds in their beaks to new ground.</p>
     <div class="figure">${ico("bee",88)}${ico("purpleFlower",88)}${ico("parrot",88)}</div>
     <p class="big">Draw a model you could really build out of things in a cabin, such as a cotton ball on a stick or a paper cone, that would pick pollen up from one flower and drop it on another.</p>`,qs:["Draw your model. Label the part that picks the pollen up.","Which animal job does your model copy, and how does your model do that job?"],key:["Any model with a part that could carry pollen and a way to move it: a cotton ball or a fuzzy stick, a brush, a sticky paper cone. The labelled carrying part is what to look for.","The bee job, moving pollen from one flower to another. Accept a seed carrier instead if the drawing shows a scoop or a beak shape that holds a seed and drops it on new ground, which copies the parrot."]}]},{id:15,title:"Two Places on the Island",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">The crew wrote down every living thing they saw in two places in one morning.</p>
     <table class="bigTable"><tr><th>The rock pool</th><th>The palm grove</th></tr>
     <tr><td>1 crab</td><td>1 parrot</td></tr>
     <tr><td>1 snail</td><td>2 kinds of beetle</td></tr>
     <tr><td>3 kinds of seaweed</td><td>1 fern</td></tr>
     <tr><td>2 kinds of small fish</td><td>1 palm tree</td></tr></table>
     <div class="figure">${ico("crab",80)}${ico("palm",80)}</div>`,qs:["How many kinds of living things are on the rock pool list?","Name one living thing from one list that could not live in the other place, and say why.","Both lists come from the same island. Why are the living things in the two places so different?"],key:["7. One crab, one snail, three seaweeds and two fish.","Any sensible pick with a reason: a small fish could not live in the palm grove because there is no water there to swim and breathe in; the palm tree could not live in the rock pool because its roots would sit in salt water.","Because the two places give different things. One is wet and salty and under water much of the day, the other is dry with soil and shade. Living things live where they can get what they need."]}]},{id:16,title:"Fast, Slow and Where the Water Is",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about the island, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>a page in the ship library book</td><td>One storm wave can pull a whole shelf of sand off a beach in a single night.</td></tr>
     <tr><td>the sign at the stone arch</td><td>Wind and water cut this arch out of the rock over thousands of years.</td></tr></table>`,qs:["Which note tells about a change to the land that happens quickly?","Which note tells about a change that takes a very long time?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The library book page, the shelf of sand pulled off in a single night.","The sign at the stone arch, cut over thousands of years.","Quick: a rockfall, a flood, a tree pushed over in a storm, a volcano. Slow: a river cutting a canyon, a cliff wearing back, a hill wearing down. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">Water turns up on nearly every part of the map the crew drew.</p>
     <div class="figure">${ico("wave",80)}${ico("drop",80)}${ico("snowflake",80)}</div>`,qs:["Name three places on Earth where you would find water.","The ocean around the island is salty. Name a place where the water is fresh instead of salty.","Snow on a mountain top is water too. Is snow solid or liquid? Is the water in the cove solid or liquid?"],key:["Any three: the ocean, a river, a lake, a pond, a stream, rain in the clouds, snow or ice on a mountain, under the ground.","A river, a lake, a pond, a stream, or rain. Most of the water on Earth is in the ocean and is salty.","Snow is solid. The water in the cove is liquid."]}]},{id:17,title:"Holding the Land, and a Map of It",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things built to stop water from changing the shape of the land",html:()=>`<p class="big">Waves kept washing the sand away from the path to the cove. The crew tried two ways to stop it and measured the sand that went missing each week.</p>
     <table class="bigTable"><tr><th>What was along the path</th><th>Sand lost in one week</th></tr>
     <tr><td>nothing at all</td><td>14 buckets</td></tr>
     <tr><td>a low wall of stones</td><td>2 buckets</td></tr>
     <tr><td>a row of beach grass</td><td>5 buckets</td></tr></table>`,qs:["Which one kept the most sand in place?","How do you know, using the chart?","Both of them beat doing nothing. Why might the crew plant the grass as well as build the wall?"],key:["the low wall of stones","Only 2 buckets of sand went missing with the wall, 5 went missing with the grass, and 14 went missing with nothing there. The reason has to come from the numbers.","Any sensible reason about holding the sand: grass roots hold the sand too, two things together would stop even more, grass is easier to put along a long path, a big wave could knock stones down."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the island. Put in a hill, a flat stretch of land, a stream, and the ocean around it. Add a key that says which is which.</p>
     <div class="figure">${ico("island",88)}${ico("mountain",88)}${ico("map",88)}</div>`,qs:["Draw your model map with the hill, the flat land, the stream and the ocean on it.","Show me your key. Which parts are land and which parts are water?","Is a stream a big body of water or a small one? Name one bigger than a stream and one smaller."],key:["All four on the page and told apart by shape or colour: a hill as a bump or as rings, flat land left flat, a stream as a line, the ocean around the outside.","Points to each part and reads the key. The key is the part that makes this a model and not just a picture.","A stream is small. Bigger: a river, a lake, the ocean. Smaller: a pond, a puddle. Accept any sensible pair."]}]},{id:18,title:"Sorting the Supply Crate",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">The crew emptied a supply crate and wrote down what each thing was made of and what they noticed about it.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What the crew noticed</th></tr>
     <tr><td>a cup</td><td>metal</td><td>hard, shiny, cold, bends only a little</td></tr>
     <tr><td>a sail patch</td><td>cloth</td><td>soft, bends easily, lets water through</td></tr>
     <tr><td>a window pane</td><td>glass</td><td>hard, smooth, you can see through it</td></tr>
     <tr><td>a lamp base</td><td>wood</td><td>hard, rough, floats</td></tr></table>`,qs:["Sort the four items into a hard group and a group that is soft or bends easily.","You want a see through pile and a cannot see through pile. Which item goes in the see through pile?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the metal cup, the glass pane, the wooden lamp base. Soft or bends easily: the cloth sail patch. If a student leaves the wood out, ask them to look at its line again.","the glass window pane","Any property that can be seen or felt and that really splits the four: floats or does not, rough or smooth, shiny or dull, lets water through or does not. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The crew need a cover to keep rain off a stack of maps. They poured one cup of water over three materials and looked underneath, then pulled on each one.</p>
     <table class="bigTable"><tr><th>Material</th><th>Water that got through</th><th>Tears when pulled</th></tr>
     <tr><td>cloth</td><td>most of it</td><td>no</td></tr>
     <tr><td>paper</td><td>a little</td><td>yes, easily</td></tr>
     <tr><td>oiled canvas</td><td>none</td><td>no</td></tr></table>`,qs:["Which material is best for the map cover?","Which two pieces of the chart make you sure?","Only a little water got through the paper. Why would paper still be a poor cover out on deck?"],key:["the oiled canvas","No water got through it, and it does not tear when it is pulled. Both columns have to be used, not just one.","It tears easily, so the wind and the crew handling it would rip it, and then the water would get straight through."]}]},{id:19,title:"Pieces, Heat and Cold",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">A small crate is on deck. It is made of 6 flat boards. It has 12 nails. The crew pulled the nails out. They laid the boards in a row.</p>
     <div class="figure">${ico("box",88)}${ico("board",88)}</div>`,qs:["The crate is gone. Are the boards gone too? What do the crew have now?","Build something new in your head out of those 6 boards. What is it, and how do the boards go together?"],key:["No. The boards are all still there. The crew have 6 boards and 12 nails, the same pieces, just not put together as a crate any more.","Any real thing from 6 flat boards: a bench, a shelf, a sign, a ramp, a small raft, a bird feeder. Listen for how the pieces join, because that is the evidence that the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened in the ship galley on the same morning.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A block of ice in a cup sat in the sun and turned into water.</td></tr>
     <tr><td>A hard biscuit sat on the hot stove top and turned black and crumbly.</td></tr></table>`,qs:["Put the cup of water somewhere cold. What happens to it?","Put the black biscuit somewhere cold. Does it turn back into a hard biscuit?","Which of the two changes can be undone, and what is your evidence?"],key:["It freezes back into ice. Cooling undoes the melting.","No. It stays black and crumbly. Nothing cold brings the biscuit back.","The ice and water change can be undone. The evidence is that the water freezes back into ice when it is cooled, and the burnt biscuit does not come back when it is cooled. Listen for the student using what happened, not just saying yes or no."]}]},{id:20,title:"The Bucket That Slides",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">Every time the ship rolls the bucket slides. The water bucket is by the galley door. It slides across the floor and spills. The crew mop it up and fill it again. An hour later it has slid again. It went across the floor once more.</p>`,qs:["What is the problem the crew want to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The bucket slides across the floor and spills when the ship rolls. Naming the sliding, not the mopping, is the problem.","Any real question: how full is the bucket, how heavy is it, how smooth is the floor, how far does it slide, is there a corner it could sit in, could it be tied down. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would hold the bucket in one place. Think hard about its shape.</p>
     <div class="figure">${ico("box",88)}${ico("anchor",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew stops the bucket from sliding."],key:["Any design that could really hold a bucket: a ring or hoop fixed to the floor, a crate the bucket sits down inside, a wooden rail across a corner, a short strap through a hook, a wide heavy base.","The shape is the part being checked. Something like: the ring goes all the way round so it cannot go sideways, the crate walls stop it, the strap is short so it can only move a little."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">The crew built both fixes and sailed one whole day with each.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Times the bucket spilled that day</th></tr>
     <tr><td>a wooden ring nailed to the floor</td><td>0</td></tr>
     <tr><td>a strap tied to a hook</td><td>3</td></tr></table>`,qs:["Which fix worked better?","How do you know?"],key:["the wooden ring nailed to the floor","The bucket spilled 0 times with the ring and 3 times with the strap. The reason has to come from the chart, not from liking rings."]}]},{id:21,title:"Long Ago and Yesterday",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four log lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the ship log.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>Sailors crossed this ocean in wooden ships with cloth sails, hundreds of years ago.</td></tr>
     <tr><td>2</td><td>Yesterday the crew drew a new map of the cove.</td></tr>
     <tr><td>3</td><td>People found their way at sea by the stars, long before there were maps like ours.</td></tr>
     <tr><td>4</td><td>This morning a crew member checked the weather on the radio.</td></tr></table>
     <p class="big">How do we know about the sailors of long ago? Four kinds of thing tell us. An artifact is an object they left behind, like a brass compass in a museum case. A photograph shows what something really looked like. An interview is what you learn by asking somebody who was there, or whose family was. A document is something written down at the time, like a ship log or a letter. All four of those are primary sources. A book somebody wrote later, after reading the logs, is a secondary source.</p>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Things that come straight from the time you are studying are called primary sources. Name two of the four kinds listed, and say which kind a ship log is."],key:["Lines 1 and 3, the wooden sailing ships and finding the way by the stars.","Lines 2 and 4, the new map yesterday and the radio check this morning.","Any two of: an artifact, a photograph, an interview, a document. A ship log is a document, and it is a primary source. Both parts are what is being checked. A student who can also say that a book written later is a secondary source has the whole of this part. (HSS-2.1)"]}]},{id:22,title:"Where Things Are",short:"Camp Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the camp map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The crew camp, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ico("palm",46)} palm grove</td><td>${ico("tent",46)} tent</td><td>${ico("sprout",46)} seed patch</td></tr>
     <tr><th>B</th><td>${ico("chest",46)} store</td><td>${ico("fire",46)} fire ring</td><td>${ico("map",46)} map table</td></tr>
     <tr><th>C</th><td>${ico("wave",46)} cove</td><td>${ico("sailboat",46)} landing</td><td>${ico("shell",46)} shell beach</td></tr></table>
     <p class="big">${ico("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the fire ring is in, using its letter and its number.","What is directly north of the fire ring?","Is the store east or west of the map table?","Which square is between the cove and the shell beach?"],key:["B2","the tent, in square A2","west. The store is in B1 and the map table is in B3, so the store is to the left, which is west.","C2, the landing"]}]},{id:23,title:"Who Decides, and Who Trades",short:"Rules and Trade",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling who makes laws and leads here, and how other countries choose a leader differently",html:()=>`<p class="big">Every place has people who make the rules and someone who leads.</p>
     <div class="figure">${ico("flag",80)}${ico("board",80)}</div>`,qs:["Who makes the laws for the whole country we live in? The people we vote for in Congress, or the crew of one ship?","What does a mayor do for a city?","In some other countries the leader is a king or a queen who was born into the job. In our country we vote for our leaders. Is that the same or different?"],key:["the people we vote for in Congress","Leads the city and helps decide the rules there. Accept: runs the city, is in charge of the city, works with the city council.","Different. Here the people vote and choose. A king or a queen is not voted for."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"telling what each side gives and gets in a trade, why people trade, and naming a job and what it produces",html:()=>`<p class="big">The crew set up a small stall at the landing to swap what they have for what they need.</p>
     <table class="bigTable"><tr><th>Who</th><th>What they bring</th><th>What they want</th></tr>
     <tr><td>the net maker</td><td>nets</td><td>dried fish</td></tr>
     <tr><td>the fisher</td><td>dried fish</td><td>a new net</td></tr>
     <tr><td>the water carrier</td><td>fresh water</td><td>a bucket</td></tr></table>`,qs:["The net maker and the fisher make a trade. What does each one give, and what does each one get?","Why do people trade instead of making everything themselves?","Name a job you know, and say what that worker makes or what help they give."],key:["The net maker gives a net and gets dried fish. The fisher gives dried fish and gets a net.","Because nobody can make everything. Each person makes or does one thing well and trades for the rest. Accept: it saves time, you get what you cannot make yourself.","Any real job with the right half: a baker makes bread, a farmer grows food, a nurse gives care, a bus driver gives rides. Listen for the goods or the help, not just the job name."]}]},{id:24,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about her. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Sally Ride loved science. She loved to find out how things worked. She trained hard. In 1983 she became the first. She was the first American woman to fly up. She went into space. She rode a spacecraft around the Earth. She ran science tests while she was up there. People had said it for a long time. This was a job for men only. After she came back she taught. She spent years teaching science to young people. She wrote books for them. She wanted girls to know something. They could do this work too.</p>
     <div class="figure">${ico("star",80)}${ico("telescope",80)}</div>`,qs:["What did Sally Ride do that no American woman had done before?","Which word fits her best from what you read: brave, careless, or unkind? Say why.","Name one way her work made a difference to other people."],key:["She flew into space. She was the first American woman to do it.","brave. Any reason taken from the text: she did a hard job nobody like her had done, she trained hard and went anyway when people said it was not for her.","Any answer from the text: she taught science to young people, she wrote books for them, she showed girls that they could do this work too."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Big Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each big word out loud.",html:()=>`<div style="text-align:center">${["carefully","disagreement","comfortable"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["carefully (care-ful-ly)","disagreement (dis-a-gree-ment)","comfortable (com-fort-a-ble)"]},3:{id:"L3",title:"Level Up: Story Clues",std:["RL.3.2"],needs:["RL.2.2"],n:1,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${FABLE}</p><p class="big">Crow learned to get ready ahead of time. Which parts of the story show that lesson?</p>`,key:["Names details that show the lesson, like Crow laughing and saying she had plenty of time, then getting cold and soaked."]},9:{id:"L9",title:"Level Up: Two-Step Problem",std:["3.OA.D.8"],needs:["2.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">Jen buys 3 packs of 6 markers. She gives away 5. How many markers does she have left?</p>`,key:["13 (3 x 6 = 18, then 18 - 5 = 13)"]},10:{id:"L10",title:"Level Up: Time Challenge",std:["3.MD.A.1"],needs:["2.MD.C.7"],n:2,dir:"Look at the clock. Answer out loud.",html:()=>`<div class="figure">${clock(7,43)}</div><ol class="qlist"><li>What time is it?</li><li>Soccer starts at 2:15. It lasts 45 minutes. What time does it end?</li></ol>`,key:["7:43 (to the nearest minute)","3:00"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.2","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let c120On={},blk=[0,0,0],pvVal=["",""],nlStart="",nlHops=[],nlShown={};function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function nlSvg(){if(nlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+nlStart];nlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;nlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+nlStart||nlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+nlStart?"":`data-v="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function nlHtml(){const j=d=>`<button class="chip" data-j="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="nlStart" value="${nlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-j="u">Undo</button><button class="chip" data-j="x">Clear</button></div><div class="tool-scroll" id="nlBox" style="text-align:center">${nlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function nlBind(b,r){const box=()=>b.querySelectorAll("[data-v]").forEach(g=>g.onclick=()=>{nlShown[g.dataset.v]=!nlShown[g.dataset.v];r()});const inp=b.querySelector("#nlStart");inp.oninput=()=>{nlStart=inp.value.replace(/[^0-9]/g,"");nlShown={};b.querySelector("#nlBox").innerHTML=nlSvg();box()};b.querySelectorAll("[data-j]").forEach(x=>x.onclick=()=>{const k=x.dataset.j;if(k==="x"){nlHops=[];nlShown={}}else if(k==="u")nlHops.pop();else if(nlStart!==""&&nlHops.length<10)nlHops.push(+k);r()});box()}const STARTERS={opinion:["I think ____.","One reason is ____.","Also, ____.","That is why ____."],facts:["Sea turtles ____.","One fact is ____.","Another fact is ____.","Now you know ____."],story:["One time, ____.","First, ____.","Next, ____.","Last, ____.","I felt ____."]};const SENTSET={"W.2.1":"opinion","W.2.2":"facts","W.2.3":"story","W.2.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].alt&&parts[0].alt.key;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return F.row(F.ruler({length:6,px:70,parts:2,unit:"in",item:4.5,itemLabel:"pencil"}))+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:nlHtml,bind:nlBind},chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},coins:{name:"Coin values",std:["2.MD.C.8"],html:()=>`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["quarter",46,SILVER,"25¢"],["dime",32,SILVER,"10¢"],["nickel",38,SILVER,"5¢"],["penny",36,COPPER,"1¢"]].map(([n,r,f,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${coin(n,r,f)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"coins",std:["2.MD.C.8"],msg:"The coin values chart supplies what each coin is worth, so the money item done with it shows adding and the cent sign, not knowing the coins. Count it as supported, not independent."},{t:"blocks",std:["2.NBT.A.1","2.NBT.A.3"],msg:"With the blocks out, Number Card shows the student can read a model of 748. It does not show they know what each digit is worth without one."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count the digit value and expanded form items as supported, not independent."},{t:"nl",msg:"Show a landing number only after the student says it. If you showed it first, the number line did that step for the student."},{t:"sent",msg:"Sentence starters supply the opening, the linking and time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
